      en: ["Completed in 1955 for Emperor Haile Selassie's Silver Jubilee.", "Current official residence and office of the President of Ethiopia.", "Known for its expansive gardens and resident lions and peacocks.", "The palace was the site of the founding of the OAU in 1963.", "Renamed the National Palace after the 1974 revolution.", "Located centrally near the Africa Hall and the Hilton Hotel."],
      es: ["Construido en 1955 para el jubileo de plata del trono de Haile Selassie.", "Sirve hoy como residencia oficial del presidente de Etiopía.", "Se encuentra muy cerca del complejo Africa Hall.", "El palacio es conocido por sus jardines y los leones imperiales.", "Fue escenario de numerosos encuentros diplomáticos históricos.", "Se convirtió en el Palacio Nacional tras la caída de la monarquía en 1974."],
      pt: ["Construído em 1955 para o jubileu de prata do trono de Haile Selassie.", "Serve hoje como residência oficial do presidente da Etiópia.", "Localiza-se nas imediações do complexo Africa Hall.", "O palácio é conhecido pelos seus jardins e pelos leões imperiais.", "Foi palco de inúmeros encontros diplomáticos históricos.", "Tornou-se o Palácio Nacional após a queda da monarquia em 1974."],
      fr: ["Construit en 1955 pour le jubilé d'argent de Haile Selassie.", "Sert aujourd'hui de résidence officielle au président de l'Éthiopie.", "Situé à proximité immédiate du complexe de l'Africa Hall.", "Le palais est réputé pour ses jardins et ses lions impériaux.", "A été le théâtre de nombreuses rencontres diplomatiques historiques.", "Est devenu le Palais national après la chute de la monarchie en 1974."],
